t(){ python3 tween.py "$1" "$2" "$3" "$4" "$5" 7 & }
FV="STRICT straight front view toward the camera the whole time, never turns to the side."
BV="STRICT straight back view the whole time, never turns to the side, red bikini back strap visible."
t b_s.png k_cast_s_x.png tw_cast_s1 4 "$FV She raises both needle-rapiers and crosses them in an X in front of her chest, no effects"
t k_cast_s_x.png k_cast_s_t.png tw_cast_s2 4 "$FV She twirls the crossed rapiers once as if winding thread, then steps and thrusts one arm forward throwing a needle, no effects"
t b_n.png k_cast_n_x.png tw_cast_n1 4 "$BV She raises both needle-rapiers and crosses them in an X in front of her chest, no effects"
t k_cast_n_x.png k_cast_n_t.png tw_cast_n2 4 "$BV She twirls the crossed rapiers once as if winding thread, then thrusts one arm forward away from the camera throwing a needle, no effects"
t b_s.png k_jump_s.png tw_jump_s 4 "$FV She bends her knees and springs straight up, tucking her knees, ponytail flying up, no effects"
t b_n.png k_jump_n.png tw_jump_n 4 "$BV She bends her knees and springs straight up, tucking her knees, ponytail flying up, no effects"
t b_s.png k_hurt_s.png tw_hurt_s 4 "$FV She gets hit and flinches backward, wincing, no effects"
t b_n.png k_hurt_n.png tw_hurt_n 4 "$BV She gets hit and flinches backward, no effects"
t b_s.png k_death_s.png tw_death_s 8 "She is defeated: her knees give out, she sinks to her knees and collapses onto her side on the ground, seen from the front, no effects"
t b_n.png k_death_n.png tw_death_n 8 "She is defeated: her knees give out, she sinks down and collapses face down on the ground, seen from behind, no effects"
t r_s.png k_rj_s.png tw_rj_s1 4 "$FV Running toward the camera she pushes off and leaps into the air, no effects"
t k_rj_s.png r_s.png tw_rj_s2 4 "$FV She lands from the leap and keeps running toward the camera, no effects"
t r_n.png k_rj_n.png tw_rj_n1 4 "$BV Running away from the camera she pushes off and leaps into the air, no effects"
t k_rj_n.png r_n.png tw_rj_n2 4 "$BV She lands from the leap and keeps running away from the camera, no effects"
t r_d.png k_rj_d.png tw_rj_d1 4 "Three-quarter front view facing down-right the whole time. Running, she pushes off and leaps forward into the air, no effects"
t k_rj_d.png r_d.png tw_rj_d2 4 "Three-quarter front view facing down-right the whole time. She lands from the leap and keeps running, no effects"
t r_u.png k_rj_u.png tw_rj_u1 4 "STRICT three-quarter BACK view facing up-right the whole time, face never visible. Running, she pushes off and leaps forward into the air, no effects"
t k_rj_u.png r_u.png tw_rj_u2 4 "STRICT three-quarter BACK view facing up-right the whole time, face never visible. She lands from the leap and keeps running, no effects"
wait
